"""Intent test for PL-01 (M1-T21): TC-15 same settings and seed, same run (RUN-02, RUN-03)."""

import csv
import json
import zipfile
from pathlib import Path
from typing import Any

import pytest

from rllab.lab.pipelines.pl01_train import run_train
from rllab.runs import RunRecord

FIXTURE = Path(__file__).resolve().parents[2] / "fixtures" / "rllab" / "TC-15"
RUN_FILES = {"settings.json", "curve.csv", "checkpoint.npz", "games.npz", "status"}


def _load(name: str) -> Any:
    return json.loads((FIXTURE / name).read_text())


def _toml_value(value: Any) -> str:
    return json.dumps(value)


def _write_settings(settings: dict[str, Any], path: Path) -> None:
    """The fixture's settings as TOML: scalars first, then one table per nested section."""
    lines = [f"{k} = {_toml_value(v)}" for k, v in settings.items() if not isinstance(v, dict)]
    for section, table in settings.items():
        if isinstance(table, dict):
            lines.append(f"[{section}]")
            lines.extend(f"{k} = {_toml_value(v)}" for k, v in table.items())
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def _curve_without_elapsed(run: Path) -> list[dict[str, str]]:
    with (run / "curve.csv").open(newline="", encoding="utf-8") as f:
        return [{k: v for k, v in row.items() if k != "elapsed_s"} for row in csv.DictReader(f)]


def _archive_members(path: Path) -> dict[str, bytes]:
    """Each stored array's bytes; the zip headers' write times are not part of the run."""
    with zipfile.ZipFile(path) as archive:
        return {name: archive.read(name) for name in archive.namelist()}


@pytest.fixture(scope="module")
def two_runs(tmp_path_factory: pytest.TempPathFactory) -> list[RunRecord]:
    spec = _load("input.json")
    root = tmp_path_factory.mktemp("tc15")
    settings_path = root / "tc15.toml"
    _write_settings(spec["settings"], settings_path)
    with pytest.MonkeyPatch.context() as patch:
        patch.chdir(root)
        return [run_train(settings_path, spec["settings"]["seed"]) for _ in range(spec["runs"])]


@pytest.mark.intent
@pytest.mark.repro
def test_tc15_each_run_folder_is_complete(two_runs: list[RunRecord]) -> None:
    assert two_runs[0].path != two_runs[1].path
    for record in two_runs:
        assert record.status == "complete"
        assert {p.name for p in record.path.iterdir()} == RUN_FILES
        assert (record.path / "status").read_text(encoding="utf-8") == "complete"
        assert [p.step for p in record.curve] == [0, 500, 1000, 1500, 2000]


@pytest.mark.intent
@pytest.mark.repro
def test_tc15_same_curve_apart_from_elapsed_time(two_runs: list[RunRecord]) -> None:
    first, second = (_curve_without_elapsed(r.path) for r in two_runs)
    assert len(first) == 5
    assert first == second


@pytest.mark.intent
@pytest.mark.repro
def test_tc15_same_checkpoint_bytes(two_runs: list[RunRecord]) -> None:
    first, second = (_archive_members(r.path / "checkpoint.npz") for r in two_runs)
    assert set(first) == {"keys.npy", "values.npy", "learns.npy"}
    assert first == second


@pytest.mark.intent
@pytest.mark.repro
def test_tc15_same_recorded_games(two_runs: list[RunRecord]) -> None:
    first, second = (_archive_members(r.path / "games.npz") for r in two_runs)
    assert len(two_runs[0].games) == 5
    assert first == second


@pytest.mark.intent
@pytest.mark.repro
def test_tc15_same_settings_json(two_runs: list[RunRecord]) -> None:
    first, second = ((r.path / "settings.json").read_bytes() for r in two_runs)
    assert first == second
    assert two_runs[0].settings == two_runs[1].settings
